// XGMII_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module XGMII_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [4:0] c_count,
  input logic  c_irq,
  input logic  c_wen,
  input logic [7:0] c_wdata,
  input logic  c_ren,
  input logic [7:0] c_rdata
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 24;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:23];          // model of every stored word
  logic [0:0] m_set;                // interrupt bits set this clock

  always_comb begin
    m_set = '0;
    if (c_irq) m_set[0] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h58470200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return (32'(c_count) << 0);
      6: return 0;
      7: return 0;
      8: return 32'(c_rdata);
      9: return 32'(c_rdata);
      10: return 32'(c_rdata);
      11: return 32'(c_rdata);
      12: return 32'(c_rdata);
      13: return 32'(c_rdata);
      14: return 32'(c_rdata);
      15: return 32'(c_rdata);
      16: return 32'(c_rdata);
      17: return 32'(c_rdata);
      18: return 32'(c_rdata);
      19: return 32'(c_rdata);
      20: return 32'(c_rdata);
      21: return 32'(c_rdata);
      22: return 32'(c_rdata);
      23: return 32'(c_rdata);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  wire        m_bus_partial = PWRITE && PSTRB != 4'hF && m_map && (m_idx == 6 || m_idx == 7);   // dropped with PSLVERR
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == (!m_map || m_bus_partial))
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][0:0] & m_w[2][0:0]))
  wire m_bus_wr_CORE = m_wr && m_map && PSTRB == 4'hF && (m_idx == 6 || m_idx == 7);
  `SVA_INV(a_core_wen, c_wen == m_bus_wr_CORE)
  `SVA_IMP(a_core_waddr_wdata, m_bus_wr_CORE, int'(u_core.waddr) == (m_idx == 6 ? 0 : m_idx == 7 ? 1 : 0) && c_wdata == PWDATA[7:0])
  wire m_bus_rd_CORE = m_rd && m_map && (m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11 || m_idx == 12 || m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16 || m_idx == 17 || m_idx == 18 || m_idx == 19 || m_idx == 20 || m_idx == 21 || m_idx == 22 || m_idx == 23);
  `SVA_INV(a_core_ren, c_ren == m_bus_rd_CORE)
  `SVA_INV(a_core_raddr, int'(u_core.raddr) == (m_bus_rd_CORE ? (m_idx == 8 ? 0 : m_idx == 9 ? 1 : m_idx == 10 ? 2 : m_idx == 11 ? 3 : m_idx == 12 ? 4 : m_idx == 13 ? 5 : m_idx == 14 ? 6 : m_idx == 15 ? 7 : m_idx == 16 ? 8 : m_idx == 17 ? 9 : m_idx == 18 ? 10 : m_idx == 19 ? 11 : m_idx == 20 ? 12 : m_idx == 21 ? 13 : m_idx == 22 ? 14 : m_idx == 23 ? 15 : 0) : 0))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && !c_wen && !c_ren)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 5)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 5)
  `FC(rd_TX, m_rd && m_map && m_idx == 6)
  `FC(wr_TX, m_wr && m_map && m_idx == 6)
  `FC(rd_EOF, m_rd && m_map && m_idx == 7)
  `FC(wr_EOF, m_wr && m_map && m_idx == 7)
  `FC(rd_RX0, m_rd && m_map && m_idx == 8)
  `FC(wr_RX0, m_wr && m_map && m_idx == 8)
  `FC(rd_RX1, m_rd && m_map && m_idx == 9)
  `FC(wr_RX1, m_wr && m_map && m_idx == 9)
  `FC(rd_RX2, m_rd && m_map && m_idx == 10)
  `FC(wr_RX2, m_wr && m_map && m_idx == 10)
  `FC(rd_RX3, m_rd && m_map && m_idx == 11)
  `FC(wr_RX3, m_wr && m_map && m_idx == 11)
  `FC(rd_RX4, m_rd && m_map && m_idx == 12)
  `FC(wr_RX4, m_wr && m_map && m_idx == 12)
  `FC(rd_RX5, m_rd && m_map && m_idx == 13)
  `FC(wr_RX5, m_wr && m_map && m_idx == 13)
  `FC(rd_RX6, m_rd && m_map && m_idx == 14)
  `FC(wr_RX6, m_wr && m_map && m_idx == 14)
  `FC(rd_RX7, m_rd && m_map && m_idx == 15)
  `FC(wr_RX7, m_wr && m_map && m_idx == 15)
  `FC(rd_RX8, m_rd && m_map && m_idx == 16)
  `FC(wr_RX8, m_wr && m_map && m_idx == 16)
  `FC(rd_RX9, m_rd && m_map && m_idx == 17)
  `FC(wr_RX9, m_wr && m_map && m_idx == 17)
  `FC(rd_RX10, m_rd && m_map && m_idx == 18)
  `FC(wr_RX10, m_wr && m_map && m_idx == 18)
  `FC(rd_RX11, m_rd && m_map && m_idx == 19)
  `FC(wr_RX11, m_wr && m_map && m_idx == 19)
  `FC(rd_RX12, m_rd && m_map && m_idx == 20)
  `FC(wr_RX12, m_wr && m_map && m_idx == 20)
  `FC(rd_RX13, m_rd && m_map && m_idx == 21)
  `FC(wr_RX13, m_wr && m_map && m_idx == 21)
  `FC(rd_RX14, m_rd && m_map && m_idx == 22)
  `FC(wr_RX14, m_wr && m_map && m_idx == 22)
  `FC(rd_RX15, m_rd && m_map && m_idx == 23)
  `FC(wr_RX15, m_wr && m_map && m_idx == 23)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_READ_set, m_set[0])
  `FC(irq_READ_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_READ_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_READ_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(core_register_partial_write, m_wr && m_bus_partial)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind XGMII_apb XGMII_apb_sva u_apb_sva (.*);
